Task: Your task is to complete a JavaScript class hierarchy for electronic gadgets. Implement proper inheritance for the `Smartwatch` class from the `Gadget` base class, and ensure robust input validation for battery levels. Focus on clean, readable code and handle the edge case of invalid battery input.

Submitted code:
```
class Gadget {
    constructor(name, batteryLevel) {
        this.name = name;

        // Validation: Ensure battery is between 0 and 100
        if (batteryLevel < 0 || batteryLevel > 100) {
            throw new Error("Battery level must be between 0 and 100.");
        }

        this.batteryLevel = batteryLevel;
    }

    get batteryStatus() {
        return `${this.name} battery: ${this.batteryLevel}%`;
    }
}

class Smartwatch extends Gadget {
    constructor(name, batteryLevel, currentTime) {
        // Initialize the parent class (Gadget)
        super(name, batteryLevel);
        this.currentTime = currentTime;
    }

    displayInfo() {
        // Leveraging the parent's logic to maintain a single source of truth
        return `${this.batteryStatus}, Time: ${this.currentTime}`;
    }
}

// --- Usage ---
try {
    const myWatch = new Smartwatch("MyWatch", 85, "10:30 AM");
    console.log(myWatch.displayInfo()); 
    // Output: MyWatch battery: 85%, Time: 10:30 AM
} catch (error) {
    console.error(error.message);
}

```

